<?php
namespace App\Jobs;use App\Contracts\FaceProvider;use App\Models\ProviderDeletionOperation;use Illuminate\Bus\Queueable;use Illuminate\Contracts\Queue\ShouldQueue;use Illuminate\Foundation\Bus\Dispatchable;use Illuminate\Queue\{InteractsWithQueue,SerializesModels};use Throwable;
class ExecuteProviderDeletion implements ShouldQueue{use Dispatchable,InteractsWithQueue,Queueable,SerializesModels;public int$tries=5;public function __construct(public int$operationId){$this->onQueue('maintenance');}public function backoff():array{return[30,120,600,1800];}public function handle(FaceProvider$p):void{$o=ProviderDeletionOperation::findOrFail($this->operationId);if($o->state==='completed')return;$o->increment('attempts');$o->update(['state'=>'processing']);try{$r=$o->provider_references;$o->operation==='collection'?$p->deleteCollection($r['collection']):$p->removeFaces($r['collection'],$r['face_ids']);$o->update(['state'=>'completed','completed_at'=>now(),'error'=>null]);}catch(Throwable$e){$o->update(['state'=>'failed','error'=>'Provider deletion failed.']);throw$e;}}}
